  const siloMetrics = telemetries.filter(t => t.metric_type === 'silo');

  const totalSiloCap = siloMetrics.reduce((s, x) => s + (parseFloat(x.capacity) || 0), 0);
  const totalSiloVal = siloMetrics.reduce((s, x) => s + (parseFloat(x.value) || 0), 0);
  const siloFillPct = totalSiloCap > 0 ? Math.round((totalSiloVal / totalSiloCap) * 100) : 78;

  const currentAnimal = realAnimals.length > 0 ? realAnimals[0] : MOCK_ANIMAL;

