        m.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        m.cat.toLowerCase().includes(searchQuery.toLowerCase()) ||
        m.num.toLowerCase().includes(searchQuery.toLowerCase());
      return matchTab && matchSearch;
